font-shorthand.call:
$config: m.private-typography-to-2018-config(m.get-typography-config($__theme));
.mat-h5,
.mat-typography .mat-h5,
.mat-typography h5 {
  @include m.font-shorthand(
    calc(#{m.font-size($config, body-2)} * 0.83),
    m.font-weight($config, body-2),
    m.line-height($config, body-2),
    m.font-family($config, body-2)
  );
  margin: 0 0 12px;
}

