private-check-duplicate-theme-styles.call:
$theme: m.private-legacy-get-theme($__theme);
@include m.private-check-duplicate-theme-styles($theme, 'mat-card') {
  $color: m.get-color-config($theme);
  $density: m.get-density-config($theme);
  $typography: m.get-typography-config($theme);
  @if $color != null {
    @include m.card-color($color);
  }
  @if $density != null {
    @include m.card-density($density);
  }
  @if $typography != null {
    @include m.card-typography($typography);
  }
}

